Method.Implementation:

 try {
	Set img = %page.%GetComponentById("TemplateLogo")
    Set stream=##class(%FileBinaryStream).%New()

    if $$$ISOK(stream.LinkToFile("/WORK/common/images/intermountain.jpg"))
    {
     Set oid=stream.%Oid()
     Set img.streamId = oid 
   }
 } catch err
 {
 }

   Quit $$$OK

try {
	var un = zenPage.getComponentById('txtUsername').getValue();
	var pw = zenPage.getComponentById('txtPassword').getValue();
	if(un == '' || pw == '')
	{
		zenPage.getComponentById('lblAccess').setValue('Login with LDAP password (try again)');
		zenPage.getComponentById('lblAccess').setProperty('hidden', false);
	}
	else
	{
		zenPage.getComponentById('lblAccess').setValue('Initializing');
		zenPage.getComponentById('lblAccess').setProperty('hidden', false);

		var res = zenPage.ValidateSubversionUser();
		if(res == 0)

		{
			var pg = zenPage.getComponentById('comboboxFunction').getValue()
			if (pg == "srcCtrl")
			{
				zenPage.gotoPage("IHC.ITF.SrcCtrlPkg.SrcCtrlPage.cls");
			}
			else
			{
				zenPage.gotoPage("IHC.ITF.SrcCtrlPkg.Deployment.cls");
			}
		}

	}
}
catch (ex) {
	zenExceptionHandler(ex,arguments);
}

if(evt.keyCode == 13)
{
	zenPage.validateFields()
}
else
{
	zenPage.getComponentById('lblAccess').setProperty('hidden', true);
}
return true;

	#dim %page as %ZEN.Component.page
	Try {

		set un = %page.%GetValueById("txtUsername")
		set pw = %page.%GetValueById("txtPassword")
 		Do ##class(IHC.ITF.ITFCOMMON.Utility).ClearItfDebug(un)
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(un, $SYSTEM _ ", " _ $NAMESPACE _ ", " _ $ZV _ ", " _  $USERNAME  _", " _ $THIS)
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(un, $SYSTEM _ ": " _ $ZDATETIME($HOROLOG) _ " In ValidateSubversionUser for: " _ un)
		set stat = 0

		set cmd = "svn --username " _ un _ " --password '" _ pw _ "' --non-interactive --no-auth-cache  info https://subversion.co.ihc.com/ITF_Ensemble"
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(un, $SYSTEM _ " Check user for SVN: " _ un)
        Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd(cmd)


        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(un, "Check user for SVN: " _ un _ ", stat: " _ stat)
		if (stat '= 0)
		{
			Do %page.%SetValueById("lblAccess","Could not access Subversion with given Username / Password")
			Set %page.%GetComponentById("lblAccess").hidden = 0
		}
		else
		{
			set %session.Data("PsWd") = pw
			set %session.Data("UsNm") = un

		}
		// &js<alert('Server Method');>
	}
	Catch(ex) {
		&js<alert('Could not run SVN command to check the user, possible permission issue, error in Server method:\n#($ZCVT(ex.DisplayString(),"O","JS"))#');>
	}
	Quit stat
